-- Legal, IP & Data: four combined questions split (LG01/LG08, LG03/LG09, LG04/LG10, LG05/LG11).
update public.hub_chk_points set q='Is every brand name registered as a trademark in the correct firm''s name?', why='An unregistered brand can be copied or even claimed by others.', law='Trade Marks Act 1999', evidence='Trademark register (see Trademarks tab)', updated_at=now() where code='LG01';
update public.hub_chk_points set q='Are third-party manufacturing, supply and distributor agreements signed and stamped?', why='An unsigned agreement is hard to enforce.', law='Indian Contract Act 1872; Stamp Act', evidence='Signed and stamped agreements', updated_at=now() where code='LG03';
update public.hub_chk_points set q='Do we give customers and employees a clear privacy notice before collecting personal data?', why='Penalties under the new data law are very high.', law='DPDP Act 2023; DPDP Rules 2025', evidence='Privacy notice', updated_at=now() where code='LG04';
update public.hub_chk_points set q='Are websites and domain names owned in the firm''s name?', why='Domains in an employee''s or agency''s name are a real risk.', law='IT Act 2000', evidence='Domain ownership list', updated_at=now() where code='LG05';
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('LG08','Legal, IP & Data','Are trademark renewal dates tracked?','A missed renewal can cancel the trademark.','Trade Marks Act 1999','',array[]::text[],'M','Renewal date list',9708,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('LG09','Legal, IP & Data','Are these agreements filed in one indexed place?','Agreements that cannot be found cannot be enforced in time.','Indian Contract Act 1872','',array[]::text[],'M','Agreement index',9709,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('LG10','Legal, IP & Data','Do we take consent before collecting personal data?','Penalties under the new data law are very high.','DPDP Act 2023; DPDP Rules 2025','',array[]::text[],'H','Consent records',9710,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('LG11','Legal, IP & Data','Do our websites carry terms and privacy pages?','Required for marketplaces, payment partners and the data law.','IT Act 2000; DPDP Act 2023','',array[]::text[],'L','Website terms and privacy page links',9711,true,null) on conflict (code) do nothing;
